import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import pageDates from './data/page-dates.json';

/**
 * Two things per page, both metadata only (no visible copy changes):
 *
 * 1. "Last updated" fallback. Starlight reads that date from git, but the
 *    Vercel build has no git history, so production showed no date. The
 *    fallback is the newest commit time from src/data/page-dates.json
 *    (generated by `npm run dates` from this repo's git log).
 * 2. JSON-LD describing the site (Organization, WebSite) and the page,
 *    with the same dates and the author already credited in the footer.
 */

const SITE = 'https://zcash.school';
const dates = pageDates as Record<string, { published: string; modified: string }>;

const author = {
	'@type': 'Person',
	'@id': 'https://adampang.com/#person',
	name: 'Adam Pang',
	alternateName: 'Adam Pangelinan',
	url: 'https://adampang.com',
};

const organization = {
	'@type': 'Organization',
	'@id': `${SITE}/#organization`,
	name: 'zcash.school',
	url: `${SITE}/`,
	logo: `${SITE}/apple-touch-icon.png`,
	description:
		'Independent educational project under the Zcash Network School program, supported by a Zcash Foundation community grant. Not affiliated with the Electric Coin Company or the Zcash Foundation.',
	sameAs: ['https://github.com/adamtpang/zcash.school'],
};

const website = {
	'@type': 'WebSite',
	'@id': `${SITE}/#website`,
	name: 'zcash.school',
	url: `${SITE}/`,
	inLanguage: 'en',
	publisher: { '@id': organization['@id'] },
};

const COURSE_DIRS = ['intro/', 'zk/', 'protocol/', 'using/', 'ecosystem/'];

export const onRequest = defineRouteMiddleware((context) => {
	const route = context.locals.starlightRoute;
	const key = route.entry.filePath.split('\\').join('/').replace(/^.*?(src\/content\/docs\/)/, '$1');
	const known = dates[key];

	if (!route.lastUpdated && known) route.lastUpdated = new Date(known.modified);

	const id = route.id;
	if (id === '404') return;

	const url = new URL(context.url.pathname, SITE).href;
	let type = 'WebPage';
	if (COURSE_DIRS.some((dir) => id.startsWith(dir))) type = 'TechArticle';
	else if (id.startsWith('blog/') && id !== 'blog') type = 'BlogPosting';

	const page: Record<string, unknown> = {
		'@type': type,
		'@id': `${url}#page`,
		url,
		name: route.entry.data.title,
		description: route.entry.data.description,
		inLanguage: 'en',
		isPartOf: { '@id': website['@id'] },
		publisher: { '@id': organization['@id'] },
		author: { '@id': author['@id'] },
	};
	if (type !== 'WebPage') {
		page.headline = route.entry.data.title;
		page.mainEntityOfPage = url;
	}
	if (known) page.datePublished = known.published;
	if (route.lastUpdated) page.dateModified = route.lastUpdated.toISOString();

	route.head.push({
		tag: 'script',
		attrs: { type: 'application/ld+json' },
		content: JSON.stringify({ '@context': 'https://schema.org', '@graph': [organization, website, author, page] }).replace(/</g, '\\u003c'),
	});
});
